declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('billing.services.manage');$pdo=db();$id=max(1,(int)($_GET['id']??$_POST['id']??0));$st=$pdo->prepare("SELECT d.*,c.company_name FROM deals d LEFT JOIN clients c ON c.id=d.client_id WHERE d.id=?");$st->execute([$id]);$deal=$st->fetch();if(!$deal){http_response_code(404);exit('Negocio no encontrado.');}if($deal['status']!=='won'){flash('error','El negocio debe estar Cerrado ganado antes de convertirlo.');redirect('deal_view.php?id='.$id);}if(!empty($deal['converted_service_id'])){flash('success','Este negocio ya fue convertido en servicio activo.');redirect('service_form.php?id='.(int)$deal['converted_service_id'].'&billing=1');}
$pageTitle='Convertir negocio ganado';$catalog=$pdo->query("SELECT * FROM service_catalog WHERE is_active=1 ORDER BY category,name_es")->fetchAll();$users=$pdo->query("SELECT id,name FROM users WHERE is_active=1 ORDER BY name")->fetchAll();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$clientId=(int)$deal['client_id'];$name=trim((string)($_POST['name']??$deal['title']));$frequency=(string)($_POST['billing_frequency']??'monthly');if(!isset(billing_frequency_options()[$frequency]))$frequency='monthly';$interval=($_POST['billing_interval_months']??'')!==''?max(1,(int)$_POST['billing_interval_months']):null;$start=(string)($_POST['start_date']??date('Y-m-d'));$nextBilling=(string)($_POST['next_billing_date']??'');$nextRenewal=(string)($_POST['next_renewal_date']??'');$amount=max(0,(float)($_POST['amount']??$deal['amount']));$currency=(string)($_POST['currency']??$deal['currency']);if(!in_array($currency,['CLP','USD','BRL'],true))$currency='USD';$catalogId=!empty($_POST['catalog_service_id'])?(int)$_POST['catalog_service_id']:null;$owner=!empty($_POST['owner_user_id'])?(int)$_POST['owner_user_id']:(int)($deal['owner_user_id']??0);$contract=match($frequency){'monthly'=>'monthly','annual'=>'annual','one_time'=>'one_time',default=>'custom'};$contractMonths=$contract==='custom'?(billing_frequency_months($frequency,$interval)?:$interval):null;if(!$nextBilling)$nextBilling=$frequency==='one_time'?$start:(billing_next_date($start,$frequency,$interval)?:$start);if(!$nextRenewal&&$frequency!=='one_time')$nextRenewal=$frequency==='annual'?billing_next_date($start,'annual'):null;$expiration=$nextRenewal?:($frequency!=='one_time'?billing_next_date($start,$frequency,$interval):null);if(!$clientId)$errors[]='El negocio no tiene cliente. Asigna un cliente antes de convertirlo.';if($name==='')$errors[]='El servicio necesita un nombre.';
if(!$errors){$sql="INSERT INTO client_services(client_id,catalog_service_id,name,category,description,contract_type,custom_period_months,start_date,expiration_date,amount,currency,payment_status,auto_renew,deal_id,owner_user_id,billing_enabled,billing_frequency,billing_interval_months,next_billing_date,next_renewal_date,auto_generate_charges,billing_status,billing_alert_days,billing_notify_email,billing_notify_whatsapp,billing_notify_inapp,status,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";$category=null;$description=null;if($catalogId){foreach($catalog as$cat)if((int)$cat['id']===$catalogId){$category=$cat['category'];$description=$cat['description_es']?:null;if($name===$deal['title'])$name=$cat['name_es'];break;}}$pdo->prepare($sql)->execute([$clientId,$catalogId,$name,$category,$description,$contract,$contractMonths,$start,$expiration,$amount,$currency,'pending',isset($_POST['auto_renew'])?1:0,$id,$owner?:null,1,$frequency,$frequency==='custom'?$interval:null,$nextBilling,$nextRenewal,isset($_POST['auto_generate_charges'])?1:0,'active',trim((string)($_POST['billing_alert_days']??'30,15,7,3,1,0,-3')),isset($_POST['billing_notify_email'])?1:0,isset($_POST['billing_notify_whatsapp'])?1:0,isset($_POST['billing_notify_inapp'])?1:0,'active',trim((string)($_POST['notes']??''))?:null]);$serviceId=(int)$pdo->lastInsertId();billing_ensure_charge_for_service($serviceId,$nextBilling,(int)$_SESSION['user_id']);$pdo->prepare('UPDATE deals SET converted_service_id=?,converted_at=NOW() WHERE id=?')->execute([$serviceId,$id]);log_activity('Negocio ganado convertido en servicio',$clientId,$serviceId,$deal['title']);flash('success','Negocio convertido. El servicio activo y su primer cobro ya están en Facturación.');redirect('billing_services.php');}}
$v=fn(string$key,mixed$default='')=>$_POST[$key]??$default;require __DIR__.'/includes/header.php';
?>
<?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2>Convertir negocio ganado</h2><span class="table-sub"><?=e($deal['company_name']?:'Sin cliente')?> · <?=e($deal['title'])?> · <?=e(format_money($deal['amount'],$deal['currency']))?></span></div><a class="btn btn-light" href="deal_view.php?id=<?=$id?>">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Servicio del catálogo<select name="catalog_service_id"><option value="">Servicio personalizado</option><?php foreach($catalog as$c):?><option value="<?=$c['id']?>"><?=e(($c['category']?:'General').' · '.$c['name_es'])?></option><?php endforeach;?></select></label><label>Nombre del servicio<input name="name" required value="<?=e($v('name',$deal['title']))?>"></label><label>Responsable<select name="owner_user_id"><option value="">Sin asignar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=(int)$v('owner_user_id',$deal['owner_user_id'])===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Frecuencia de cobro<select name="billing_frequency"><?php foreach(billing_frequency_options() as$key=>$label):?><option value="<?=$key?>" <?=$v('billing_frequency','monthly')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Cada X meses<input type="number" name="billing_interval_months" min="1" value="<?=e($v('billing_interval_months'))?>"></label><label>Valor por período<input type="number" name="amount" min="0" step="0.01" value="<?=e($v('amount',$deal['amount']))?>"></label><label>Moneda<select name="currency"><?php foreach(['CLP','USD','BRL'] as$cur):?><option <?=$v('currency',$deal['currency'])===$cur?'selected':''?>><?=$cur?></option><?php endforeach;?></select></label><label>Inicio<input type="date" name="start_date" value="<?=e($v('start_date',date('Y-m-d')))?>"></label><label>Primer / próximo cobro<input type="date" name="next_billing_date" value="<?=e($v('next_billing_date'))?>"><span class="table-sub">Si lo dejas vacío, el CRM lo calcula.</span></label><label>Próxima renovación contractual<input type="date" name="next_renewal_date" value="<?=e($v('next_renewal_date'))?>"></label><label>Días de alerta<input name="billing_alert_days" value="<?=e($v('billing_alert_days','30,15,7,3,1,0,-3'))?>"></label><label class="checkbox-row"><input type="checkbox" name="auto_generate_charges" checked> Crear siguiente cobro automáticamente</label><label class="checkbox-row"><input type="checkbox" name="auto_renew" checked> Renovar vigencia con el pago</label><label class="checkbox-row"><input type="checkbox" name="billing_notify_inapp" checked> Alertar dentro del CRM</label><label class="checkbox-row"><input type="checkbox" name="billing_notify_email" checked> Alertar por email</label><label class="checkbox-row"><input type="checkbox" name="billing_notify_whatsapp"> Alertar por WhatsApp</label><label class="full">Notas<textarea name="notes"><?=e($v('notes'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="deal_view.php?id=<?=$id?>">Cancelar</a><button class="btn btn-primary">CONVERTIR Y CREAR FACTURACIÓN</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
